-- PostgreSQL schema version 1; domain schema corresponds to SQLite version 8.
-- UTC timestamps stay as fixed-width text to preserve existing snapshots/reports.
CREATE TABLE addresses(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL,label TEXT NOT NULL,recipient TEXT NOT NULL,phone TEXT NOT NULL,address TEXT NOT NULL,is_default BIGINT NOT NULL DEFAULT 0 CHECK(is_default IN (0,1)),version BIGINT NOT NULL DEFAULT 1);
CREATE TABLE app_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE attribute_definitions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,category_id BIGINT NOT NULL,code TEXT NOT NULL,label TEXT NOT NULL,data_type TEXT NOT NULL CHECK(data_type IN ('TEXT','NUMBER','BOOLEAN')),unit TEXT NOT NULL DEFAULT '',required BIGINT NOT NULL DEFAULT 0 CHECK(required IN (0,1)),version BIGINT NOT NULL DEFAULT 1,UNIQUE(category_id,code));
CREATE TABLE audit_logs(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor_id BIGINT,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id BIGINT NOT NULL,before_json TEXT,after_json TEXT,created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE brands(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL UNIQUE,slug TEXT NOT NULL UNIQUE,active BIGINT NOT NULL DEFAULT 1 CHECK(active IN (0,1)));
CREATE TABLE categories(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL UNIQUE,slug TEXT NOT NULL UNIQUE,active BIGINT NOT NULL DEFAULT 1 CHECK(active IN (0,1)));
CREATE TABLE checkout_requests(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL,request_key TEXT NOT NULL,quote_json TEXT NOT NULL,expires_at BIGINT NOT NULL,payload_hash TEXT,order_id BIGINT UNIQUE, shipping_fee BIGINT NOT NULL DEFAULT 0 CHECK(shipping_fee>=0), promotion_id BIGINT, promotion_code TEXT NOT NULL DEFAULT '', discount BIGINT NOT NULL DEFAULT 0 CHECK(discount>=0), payment_method TEXT NOT NULL DEFAULT 'COD' CHECK(payment_method IN ('COD','ONLINE')),UNIQUE(user_id,request_key),CHECK((order_id IS NULL AND payload_hash IS NULL) OR (order_id IS NOT NULL AND payload_hash IS NOT NULL)));
CREATE TABLE cod_receipts(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id BIGINT NOT NULL UNIQUE,actor_id BIGINT NOT NULL,amount BIGINT NOT NULL CHECK(amount>0),reference TEXT NOT NULL UNIQUE,note TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE inventory_movements(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,variant_id BIGINT NOT NULL,actor_id BIGINT,on_hand_delta BIGINT NOT NULL,reserved_delta BIGINT NOT NULL,source_key TEXT NOT NULL UNIQUE,reason TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE inventory_reservations(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_item_id BIGINT NOT NULL UNIQUE,variant_id BIGINT NOT NULL,quantity BIGINT NOT NULL CHECK(quantity>0),status TEXT NOT NULL CHECK(status IN ('HELD','RELEASED','CONSUMED')));
CREATE TABLE "order_history"(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id BIGINT NOT NULL,actor_id BIGINT,status TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')),previous_status TEXT,note TEXT NOT NULL DEFAULT '',source TEXT NOT NULL DEFAULT 'USER' CHECK(source IN ('USER','SYSTEM','PROVIDER')));
CREATE TABLE order_items (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL, product_id BIGINT NOT NULL, name TEXT NOT NULL, price BIGINT NOT NULL, quantity BIGINT NOT NULL CHECK(quantity > 0), variant_id BIGINT, sku_snapshot TEXT NOT NULL DEFAULT '', configuration_snapshot TEXT NOT NULL DEFAULT '');
CREATE TABLE orders (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, recipient TEXT NOT NULL, phone TEXT NOT NULL, address TEXT NOT NULL, total BIGINT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING', payment_method TEXT NOT NULL DEFAULT 'COD', payment_status TEXT NOT NULL DEFAULT 'UNPAID', created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')), version BIGINT NOT NULL DEFAULT 1, subtotal BIGINT NOT NULL DEFAULT 0 CHECK(subtotal>=0), shipping_fee BIGINT NOT NULL DEFAULT 0 CHECK(shipping_fee>=0), discount BIGINT NOT NULL DEFAULT 0 CHECK(discount>=0 AND (discount=0 OR discount<subtotal)), promotion_code TEXT NOT NULL DEFAULT '', payment_deadline BIGINT, recognition_at TEXT);
CREATE TABLE password_resets(user_id BIGINT PRIMARY KEY,token_hash TEXT NOT NULL UNIQUE,auth_version BIGINT NOT NULL,expires_at BIGINT NOT NULL);
CREATE TABLE payment_events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,payment_id BIGINT NOT NULL,event_key TEXT NOT NULL UNIQUE,response_code TEXT NOT NULL,transaction_status TEXT NOT NULL,outcome TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE payments(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id BIGINT NOT NULL,provider TEXT NOT NULL CHECK(provider IN ('COD','VNPAY')),reference TEXT NOT NULL UNIQUE,amount BIGINT NOT NULL CHECK(amount>0),status TEXT NOT NULL CHECK(status IN ('PENDING','FAILED','EXPIRED','SUCCEEDED')),provider_transaction_id TEXT,created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')),expires_at BIGINT,occurred_at TEXT,evidence_ref TEXT,ip_address TEXT NOT NULL DEFAULT '127.0.0.1',UNIQUE(provider,provider_transaction_id));
CREATE TABLE product_images(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,product_id BIGINT NOT NULL,storage_key TEXT NOT NULL UNIQUE,data BYTEA NOT NULL,mime TEXT NOT NULL DEFAULT 'image/webp',alt_text TEXT NOT NULL,sort_order BIGINT NOT NULL DEFAULT 0 CHECK(sort_order>=0));
CREATE TABLE product_variants(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,product_id BIGINT NOT NULL,sku TEXT NOT NULL UNIQUE,color TEXT NOT NULL DEFAULT '',configuration TEXT NOT NULL DEFAULT '',price BIGINT CHECK(price>0 AND price<=1000000000),on_hand BIGINT NOT NULL DEFAULT 0,reserved BIGINT NOT NULL DEFAULT 0,active BIGINT NOT NULL DEFAULT 0 CHECK(active IN (0,1)),version BIGINT NOT NULL DEFAULT 1,CHECK(on_hand>=reserved AND reserved>=0 AND on_hand<=1000000),CHECK(active=0 OR price IS NOT NULL));
CREATE TABLE products (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, brand TEXT NOT NULL, description TEXT NOT NULL, price BIGINT NOT NULL CHECK(price > 0), stock BIGINT NOT NULL CHECK(stock >= 0), active BIGINT NOT NULL DEFAULT 1, category_id BIGINT, brand_id BIGINT, status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('DRAFT','ACTIVE','HIDDEN')), version BIGINT NOT NULL DEFAULT 1);
CREATE TABLE promotion_products(promotion_id BIGINT NOT NULL,product_id BIGINT NOT NULL,PRIMARY KEY(promotion_id,product_id));
CREATE TABLE promotion_redemptions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,promotion_id BIGINT NOT NULL,user_id BIGINT NOT NULL,order_id BIGINT NOT NULL UNIQUE,amount BIGINT NOT NULL CHECK(amount>0),status TEXT NOT NULL CHECK(status IN ('HELD','USED','RELEASED')),created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE promotions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,code TEXT NOT NULL  UNIQUE,
    kind TEXT NOT NULL CHECK(kind IN ('FIXED','PERCENT')),value BIGINT NOT NULL CHECK(value>0),cap BIGINT CHECK(cap>0),
    minimum BIGINT NOT NULL DEFAULT 0 CHECK(minimum>=0),scope TEXT NOT NULL CHECK(scope IN ('ALL','PRODUCT')),
    starts_at BIGINT NOT NULL,ends_at BIGINT NOT NULL CHECK(ends_at>starts_at),
    total_limit BIGINT NOT NULL CHECK(total_limit>0),user_limit BIGINT NOT NULL CHECK(user_limit>0 AND user_limit<=total_limit),
    active BIGINT NOT NULL DEFAULT 1 CHECK(active IN (0,1)),version BIGINT NOT NULL DEFAULT 1,
    CHECK(kind='FIXED' OR (value<=100 AND cap IS NOT NULL)));
CREATE TABLE refunds(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,payment_id BIGINT NOT NULL UNIQUE,order_id BIGINT NOT NULL,actor_id BIGINT NOT NULL,amount BIGINT NOT NULL CHECK(amount>0),reference TEXT NOT NULL UNIQUE,evidence_ref TEXT NOT NULL,note TEXT NOT NULL,occurred_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE request_limits(key_hash TEXT PRIMARY KEY,count BIGINT NOT NULL,expires_at BIGINT NOT NULL);
CREATE TABLE reviews(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_item_id BIGINT NOT NULL UNIQUE,rating BIGINT NOT NULL CHECK(rating BETWEEN 1 AND 5),content TEXT NOT NULL CHECK(length(trim(content)) BETWEEN 1 AND 2000),status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','HIDDEN','REJECTED')),version BIGINT NOT NULL DEFAULT 1,moderator_id BIGINT,moderation_reason TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')),updated_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE schema_migrations(version BIGINT PRIMARY KEY,name TEXT NOT NULL,applied_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE sessions(sid TEXT PRIMARY KEY,data TEXT NOT NULL,expires_at BIGINT NOT NULL);
CREATE TABLE shipping_policy(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY CHECK(id=1),fee BIGINT NOT NULL CHECK(fee BETWEEN 0 AND 1000000),version BIGINT NOT NULL DEFAULT 1);
CREATE TABLE support_history(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,request_id BIGINT NOT NULL,actor_id BIGINT NOT NULL,previous_status TEXT,status TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE support_messages(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,request_id BIGINT NOT NULL,actor_id BIGINT NOT NULL,content TEXT NOT NULL,internal BIGINT NOT NULL DEFAULT 0 CHECK(internal IN (0,1)),created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE support_requests(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL,order_id BIGINT NOT NULL,subject TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','IN_PROGRESS','RESOLVED','CLOSED')),assigned_to BIGINT,version BIGINT NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')),updated_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS')),closed_at TEXT);
CREATE TABLE users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'CUSTOMER' CHECK(role IN ('CUSTOMER','STAFF','ADMIN')), status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','LOCKED')), auth_version BIGINT NOT NULL DEFAULT 1, version BIGINT NOT NULL DEFAULT 1, phone TEXT NOT NULL DEFAULT '', address TEXT NOT NULL DEFAULT '');
CREATE TABLE variant_attribute_values(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,variant_id BIGINT NOT NULL,attribute_id BIGINT NOT NULL,value_text TEXT,value_number DOUBLE PRECISION,value_boolean BIGINT CHECK(value_boolean IN (0,1)),UNIQUE(variant_id,attribute_id),CHECK(((value_text IS NOT NULL)::integer)+((value_number IS NOT NULL)::integer)+((value_boolean IS NOT NULL)::integer)=1));
